CREATE OR REPLACE FUNCTION public.mark_free_work_category_bell(_entry uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE e public.free_work_entries;BEGIN SELECT * INTO e FROM public.free_work_entries WHERE id=_entry AND user_id=auth.uid();IF e.id IS NULL OR NOT public.account_allowed(auth.uid()) THEN RAISE EXCEPTION 'OWN_ENTRY_REQUIRED';END IF;INSERT INTO public.free_work_interests(entry_id,source,user_id,section,category,area) VALUES(e.id::text,'category',auth.uid(),e.section,e.category,e.area) ON CONFLICT DO NOTHING;END $$;
REVOKE ALL ON FUNCTION public.mark_free_work_category_bell(uuid) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.mark_free_work_category_bell(uuid) TO authenticated;